# -*- coding: utf-8 -*-
"""
Simorgh download site by ActStory.
Single file: Flask + SQLite + HTML/CSS/JS + the APK itself (embedded as base64).

Render:
  Build command : pip install flask gunicorn
  Start command : gunicorn app:app --bind 0.0.0.0:$PORT --workers 1 --timeout 120
"""
import base64
import hashlib
import os
import secrets
import sqlite3
import tempfile
import time

from flask import Flask, abort, g, jsonify, request, send_file

