def ensure_apk():
    """Decode the embedded APK to disk once, then drop it from memory."""
    global _APK_B64
    if not os.path.exists(APK_PATH):
        data = base64.b64decode("".join(_APK_B64.split()))
        tmp = APK_PATH + ".part"
        with open(tmp, "wb") as f:
            f.write(data)
        os.replace(tmp, APK_PATH)
    _APK_B64 = None


def init_db():
    os.makedirs(os.path.dirname(DB_PATH) or ".", exist_ok=True)
    with sqlite3.connect(DB_PATH) as db:
        db.execute(
            """CREATE TABLE IF NOT EXISTS acceptances (
                token TEXT PRIMARY KEY,
                ip_hash TEXT,
                user_agent TEXT,
                created_at INTEGER NOT NULL,
                downloaded_at INTEGER
            )"""
        )


ensure_apk()
init_db()


def get_db():
    if "db" not in g:
        g.db = sqlite3.connect(DB_PATH)
        g.db.row_factory = sqlite3.Row
    return g.db


@app.teardown_appcontext
def close_db(_exc):
    db = g.pop("db", None)
    if db is not None:
        db.close()


def client_hash():
    ip = request.headers.get("X-Forwarded-For", request.remote_addr or "").split(",")[0].strip()
    return hashlib.sha256((SALT + ip).encode()).hexdigest()[:24]


@app.route("/")
def index():
    size = round(os.path.getsize(APK_PATH) / (1024 * 1024), 1)
    html = PAGE.replace("__APK_NAME__", APK_NAME).replace("__SIZE__", f"{size} مگابایت")
    return html


@app.route("/api/accept", methods=["POST"])
def accept_terms():
    token = secrets.token_urlsafe(24)
    db = get_db()
    db.execute(
        "INSERT INTO acceptances (token, ip_hash, user_agent, created_at) VALUES (?, ?, ?, ?)",
        (token, client_hash(), (request.headers.get("User-Agent") or "")[:300], int(time.time())),
    )
    db.commit()
    return jsonify(url=f"/download/{token}")


@app.route("/download/<token>")
def download(token):
    db = get_db()
    row = db.execute("SELECT * FROM acceptances WHERE token = ?", (token,)).fetchone()
    if row is None or time.time() - row["created_at"] > TOKEN_TTL:
        abort(403)
    if row["downloaded_at"] is None:
        db.execute("UPDATE acceptances SET downloaded_at = ? WHERE token = ?", (int(time.time()), token))
        db.commit()
    return send_file(
        APK_PATH,
        as_attachment=True,
        download_name=APK_NAME,
        mimetype="application/vnd.android.package-archive",
    )


@app.route("/api/stats")
def stats():
    n = get_db().execute("SELECT COUNT(*) FROM acceptances WHERE downloaded_at IS NOT NULL").fetchone()[0]
    return jsonify(downloads=n)


@app.route("/healthz")
def healthz():
    return "ok"


@app.errorhandler(403)
def forbidden(_e):
    return "لینک دانلود منقضی شده است. به صفحه اصلی برگردید و دوباره قوانین را تایید کنید.", 403


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=int(os.environ.get("PORT", 5000)))
